import{_ as t,p,q as i,s,R as n,t as e,Y as c,n as o}from"./framework-e1bed10d.js";const l={},r=c(`<h1 id="vibe-coding-安全防护技巧" tabindex="-1"><a class="header-anchor" href="#vibe-coding-安全防护技巧" aria-hidden="true">#</a> Vibe Coding 安全防护技巧</h1><blockquote><p>保护你的项目和 API 密钥</p></blockquote><p>你好，我是鱼皮。</p><p>很多没有编程基础的同学在用 AI 做项目时，完全不考虑安全问题。反正代码能跑就行，至于安全不安全，等出了问题再说。但实际上，一个安全问题可能会毁掉整个项目。</p><p>我见过有人因为 API Key 泄露，一夜之间被刷了几千。也见过有人的数据库被删，所有用户数据都没了。至于那些大公司的项目，但凡出点儿问题，都会引起轩然大波。</p><p>这篇文章，我就来讲讲 Vibe Coding 中最容易忽视的安全问题，以及如何避免它们。</p><h2 id="一、致命问题-api-key-泄露" tabindex="-1"><a class="header-anchor" href="#一、致命问题-api-key-泄露" aria-hidden="true">#</a> 一、致命问题 - API Key 泄露</h2><p>在所有安全问题中，API Key 泄露是最常见、也是最致命的之一。</p><h3 id="什么是-api-key" tabindex="-1"><a class="header-anchor" href="#什么是-api-key" aria-hidden="true">#</a> 什么是 API Key？</h3><p>API Key 就像你家的钥匙，有了它，就能使用某个服务。比如 OpenAI 的 API Key 能让你调用 ChatGPT，Supabase 的 API Key 能让你访问数据库。</p><p>问题是，如果这个钥匙被别人拿到了，他们就能冒充你使用这些服务。如果是付费服务，他们会花你的钱；如果是数据库，他们可能会读取、修改甚至删除你的数据。</p><h3 id="泄露的常见方式" tabindex="-1"><a class="header-anchor" href="#泄露的常见方式" aria-hidden="true">#</a> 泄露的常见方式</h3><p>API Key 最常见的泄露方式是：<strong>直接写在代码里，然后上传到 GitHub</strong>。</p><p>很多同学可能会这样写调用 AI 大模型的代码：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// ❌ 千万不要这样做！</span>
<span class="token keyword">const</span> <span class="token constant">OPENAI_API_KEY</span> <span class="token operator">=</span> <span class="token string">&#39;sb-yupi-abc123def456...&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;https://xxx/v1/chat/completions&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
  headers<span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token string-property property">&#39;Authorization&#39;</span><span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Bearer </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">OPENAI_API_KEY</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后把代码推送到 GitHub。</p><p>结果呢？</p><p>由于你的 GitHub 项目选择了公开，任何人都能看到你的代码，也就能看到你的 API Key。更糟糕的是，有很多自动化脚本专门在 GitHub 上扫描 API Key，一旦发现就会立刻使用。</p><p>我听说过有位老哥把 OpenAI 的 API Key 直接写在了前端代码里，然后别人直接从浏览器的开发者工具里找到了他的 API Key，几个小时内就被刷了上千。等他发现时，钱已经花光了。</p><p>这个教训告诉我们：<strong>API Key 泄露不是小事，一定要重视。</strong></p><h2 id="二、如何正确管理敏感信息" tabindex="-1"><a class="header-anchor" href="#二、如何正确管理敏感信息" aria-hidden="true">#</a> 二、如何正确管理敏感信息？</h2><p>既然不能把 API Key 写在代码里，那应该怎么做呢？</p><h3 id="使用环境变量" tabindex="-1"><a class="header-anchor" href="#使用环境变量" aria-hidden="true">#</a> 使用环境变量</h3><p>正确的做法是使用环境变量。</p><p>环境变量是存储在系统或运行环境中的配置信息，不会被包含在代码里。</p><h4 id="第一步、创建-env-文件" tabindex="-1"><a class="header-anchor" href="#第一步、创建-env-文件" aria-hidden="true">#</a> 第一步、创建 .env 文件</h4><p>在项目根目录创建一个 <code>.env</code> 文件：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>OPENAI_API_KEY=sb-yupi-abc123def456...
SUPABASE_URL=https://xxx.supabase.co
SUPABASE_ANON_KEY=eyJhbGci...
DATABASE_URL=postgresql://...
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="第二步、在代码中使用" tabindex="-1"><a class="header-anchor" href="#第二步、在代码中使用" aria-hidden="true">#</a> 第二步、在代码中使用</h4><p>在代码里通过 <code>p<wbr>rocess.env</code> 访问这些变量：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// ✅ 正确的做法</span>
<span class="token keyword">const</span> <span class="token constant">OPENAI_API_KEY</span> <span class="token operator">=</span> process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">OPENAI_API_KEY</span><span class="token punctuation">;</span>

<span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;https://xxx/v1/chat/completions&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
  headers<span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token string-property property">&#39;Authorization&#39;</span><span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Bearer </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">OPENAI_API_KEY</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="第三步、添加到-gitignore" tabindex="-1"><a class="header-anchor" href="#第三步、添加到-gitignore" aria-hidden="true">#</a> 第三步、添加到 .gitignore</h4><p>确保 <code>.env</code> 文件不会被上传到 GitHub：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># .gitignore
.env
.env.local
.env.*.local
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="第四步、创建-env-example" tabindex="-1"><a class="header-anchor" href="#第四步、创建-env-example" aria-hidden="true">#</a> 第四步、创建 .env.example</h4><p>为了让其他人知道需要哪些环境变量，创建一个 <code>.env.example</code> 文件：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>OPENAI_API_KEY=your_openai_api_key_here
SUPABASE_URL=your_supabase_url_here
SUPABASE_ANON_KEY=your_supabase_key_here
DATABASE_URL=your_database_url_here
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个文件可以上传到 GitHub，因为它不包含真实的密钥。</p><h3 id="前端和后端的区别" tabindex="-1"><a class="header-anchor" href="#前端和后端的区别" aria-hidden="true">#</a> 前端和后端的区别</h3><p>这里有一个重要的区别：<strong>前端代码是公开的，后端代码是私密的。</strong></p><p>在前端（浏览器中运行的代码）中，即使你用了环境变量，最终这些值还是会被打包到 JavaScript 文件里，用户可以通过开发者工具看到。所以，<strong>绝对不要在前端代码中使用敏感的 API Key</strong>！</p><p>正确的做法是：</p><ul><li>敏感的 API 调用放在后端</li><li>前端只调用你自己的后端 API</li><li>后端验证用户身份后，再调用第三方 API</li></ul><p>通过代码举一些例子：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// ❌ 不要在前端直接调用 OpenAI</span>
<span class="token comment">// 前端代码</span>
<span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;https://api.openai.com/v1/chat/completions&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
  headers<span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token string-property property">&#39;Authorization&#39;</span><span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Bearer </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">OPENAI_API_KEY</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// ✅ 应该这样做</span>
<span class="token comment">// 前端代码：调用自己的后端</span>
<span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;/api/chat&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
  method<span class="token operator">:</span> <span class="token string">&#39;POST&#39;</span><span class="token punctuation">,</span>
  body<span class="token operator">:</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span><span class="token punctuation">{</span> message<span class="token operator">:</span> userMessage <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 后端代码：调用 OpenAI</span>
<span class="token keyword">export</span> <span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token constant">POST</span><span class="token punctuation">(</span>request<span class="token operator">:</span> Request<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> <span class="token punctuation">{</span> message <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token keyword">await</span> request<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  
  <span class="token comment">// 在后端使用 API Key</span>
  <span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;https://api.openai.com/v1/chat/completions&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    headers<span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token string-property property">&#39;Authorization&#39;</span><span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Bearer </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">OPENAI_API_KEY</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    body<span class="token operator">:</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span><span class="token punctuation">{</span> messages<span class="token operator">:</span> <span class="token punctuation">[</span><span class="token punctuation">{</span> role<span class="token operator">:</span> <span class="token string">&#39;user&#39;</span><span class="token punctuation">,</span> content<span class="token operator">:</span> message <span class="token punctuation">}</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>
  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  
  <span class="token keyword">return</span> response<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="使用密钥管理服务" tabindex="-1"><a class="header-anchor" href="#使用密钥管理服务" aria-hidden="true">#</a> 使用密钥管理服务</h3><p>如果是生产环境，建议使用专门的密钥管理服务，比如 Vercel 的环境变量管理、AWS Secrets Manager、HashiCorp Vault 等。这些服务提供了更安全的密钥存储和访问控制，大公司一般会这么做。</p><h2 id="三、其他常见安全问题" tabindex="-1"><a class="header-anchor" href="#三、其他常见安全问题" aria-hidden="true">#</a> 三、其他常见安全问题</h2><p>除了 API Key 泄露，还有一些常见的安全问题。</p><h3 id="sql-注入" tabindex="-1"><a class="header-anchor" href="#sql-注入" aria-hidden="true">#</a> SQL 注入</h3><p>SQL 注入是最经典的安全漏洞之一。如果你直接把用户输入拼接到 SQL 查询里，攻击者可以通过特殊的输入来执行恶意的 SQL 语句。</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// ❌ 危险：SQL 注入风险</span>
<span class="token keyword">const</span> query <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">SELECT * FROM users WHERE email = &#39;</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>userEmail<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">&#39;</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span>

<span class="token comment">// ✅ 安全：使用参数化查询</span>
<span class="token keyword">const</span> query <span class="token operator">=</span> <span class="token string">&#39;SELECT * FROM users WHERE email = ?&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token keyword">await</span> db<span class="token punctuation">.</span><span class="token function">execute</span><span class="token punctuation">(</span>query<span class="token punctuation">,</span> <span class="token punctuation">[</span>userEmail<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>好在，如果你用的是 Supabase、Prisma 等现代工具，它们会自动帮你防止 SQL 注入。但如果你写原始 SQL，一定要注意这个问题。</p><h3 id="xss-攻击" tabindex="-1"><a class="header-anchor" href="#xss-攻击" aria-hidden="true">#</a> XSS 攻击</h3><p>XSS（跨站脚本攻击）是指攻击者在你的网站上注入恶意脚本。</p><p>比如，如果你直接把用户输入的内容显示在页面上：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// ❌ 危险：XSS 风险</span>
<span class="token keyword">function</span> <span class="token function">Comment</span><span class="token punctuation">(</span><span class="token punctuation">{</span> text <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token operator">&lt;</span>div dangerouslySetInnerHTML<span class="token operator">=</span><span class="token punctuation">{</span><span class="token punctuation">{</span> __html<span class="token operator">:</span> text <span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token operator">/</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>攻击者可以输入 <code>&lt;script&gt;alert(&#39;鱼皮是狗&#39;)&lt;/script&gt;</code>，这段脚本就会在其他用户的浏览器中执行。</p><p><img src="https://pic.yupi.icu/1/image-20260105155517608.png" alt=""></p><p>正确的做法是：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// ✅ 安全：React 会自动转义</span>
<span class="token keyword">function</span> <span class="token function">Comment</span><span class="token punctuation">(</span><span class="token punctuation">{</span> text <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token operator">&lt;</span>div<span class="token operator">&gt;</span><span class="token punctuation">{</span>text<span class="token punctuation">}</span><span class="token operator">&lt;</span><span class="token operator">/</span>div<span class="token operator">&gt;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>React 默认会转义所有内容，除非你用 <code>dangerouslySetInnerHTML</code>。所以，<strong>除非必要，否则不要使用 <code>dangerouslySetInnerHTML</code></strong>。</p><h3 id="csrf-攻击" tabindex="-1"><a class="header-anchor" href="#csrf-攻击" aria-hidden="true">#</a> CSRF 攻击</h3><p>CSRF（跨站请求伪造）是指攻击者诱导用户在已登录的网站上执行非预期的操作。</p><p>比如你登录了银行网站，然后在另一个标签页打开了一个恶意网站。这个恶意网站里有一段代码，会自动向银行网站发送转账请求。因为你还在登录状态，银行网站会认为这是你本人的操作，就执行了转账。这就是 CSRF 攻击。</p><p>防御 CSRF 有 3 种常用方法：</p><p>1）使用 CSRF Token：服务器生成一个随机令牌，每次表单提交时都要带上这个令牌，服务器验证令牌是否正确。</p><p>2）使用 SameSite Cookie 属性：设置 Cookie 的 SameSite 属性，让浏览器只在同站请求时发送 Cookie。</p><p>3）验证请求的 Referer 头：检查请求是从哪个网站发起的，如果不是自己的网站就拒绝。</p><p>如果你用的是 Next.js、Nuxt.js 等现代框架，它们一般会自动处理 CSRF 防护。</p><h3 id="身份验证和授权" tabindex="-1"><a class="header-anchor" href="#身份验证和授权" aria-hidden="true">#</a> 身份验证和授权</h3><p>不要相信前端的任何验证！</p><p><strong>前端验证只是为了用户体验，真正的验证必须在后端做。</strong></p><p>举一些代码例子：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// ❌ 不安全：只在前端检查</span>
<span class="token keyword">function</span> <span class="token function">AdminPanel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> isAdmin <span class="token operator">=</span> localStorage<span class="token punctuation">.</span><span class="token function">getItem</span><span class="token punctuation">(</span><span class="token string">&#39;isAdmin&#39;</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string">&#39;true&#39;</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>isAdmin<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token operator">&lt;</span>div<span class="token operator">&gt;</span>无权访问<span class="token operator">&lt;</span><span class="token operator">/</span>div<span class="token operator">&gt;</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token operator">&lt;</span>div<span class="token operator">&gt;</span>管理面板<span class="token operator">&lt;</span><span class="token operator">/</span>div<span class="token operator">&gt;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token comment">// ✅ 安全：在后端验证</span>
<span class="token comment">// 前端</span>
<span class="token keyword">function</span> <span class="token function">AdminPanel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> <span class="token punctuation">{</span> data<span class="token punctuation">,</span> error <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token function">useFetch</span><span class="token punctuation">(</span><span class="token string">&#39;/api/admin/data&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>error<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token operator">&lt;</span>div<span class="token operator">&gt;</span>无权访问<span class="token operator">&lt;</span><span class="token operator">/</span>div<span class="token operator">&gt;</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token operator">&lt;</span>div<span class="token operator">&gt;</span>管理面板<span class="token operator">&lt;</span><span class="token operator">/</span>div<span class="token operator">&gt;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token comment">// 后端</span>
<span class="token keyword">export</span> <span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token constant">GET</span><span class="token punctuation">(</span>request<span class="token operator">:</span> Request<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> user <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">verifyToken</span><span class="token punctuation">(</span>request<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>user<span class="token punctuation">.</span>isAdmin<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Response</span><span class="token punctuation">(</span><span class="token string">&#39;Forbidden&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> status<span class="token operator">:</span> <span class="token number">403</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token comment">// 返回数据</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="依赖包的安全" tabindex="-1"><a class="header-anchor" href="#依赖包的安全" aria-hidden="true">#</a> 依赖包的安全</h3><p>如果你的项目用了很多第三方包，这些包也可能有安全漏洞。</p><p>城门失火殃及池鱼，建议定期运行 <code>npm audit</code> 命令检查漏洞。</p><p>如果发现漏洞，运行下列命令，它会自动更新有漏洞的包。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">npm</span> audit fix
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>对于无法自动修复的漏洞，要手动检查并决定是否需要更换包。</p><h2 id="四、安全检查清单" tabindex="-1"><a class="header-anchor" href="#四、安全检查清单" aria-hidden="true">#</a> 四、安全检查清单</h2><p>每次发布项目前，建议结合 AI + 人工过一遍这个清单。</p><h3 id="密钥和敏感信息" tabindex="-1"><a class="header-anchor" href="#密钥和敏感信息" aria-hidden="true">#</a> 密钥和敏感信息</h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 所有 API Key 都使用环境变量</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> .env 文件已添加到 .gitignore</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 创建了 .env.example 文件</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 敏感的 API 调用都在后端进行</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 没有在前端代码中暴露密钥</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 生产环境的密钥和开发环境不同</li></ul><h3 id="用户输入验证" tabindex="-1"><a class="header-anchor" href="#用户输入验证" aria-hidden="true">#</a> 用户输入验证</h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 所有用户输入都经过验证</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 前端和后端都做了验证</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 使用了参数化查询，防止 SQL 注入</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 避免使用 dangerouslySetInnerHTML</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 对用户上传的文件进行了类型和大小检查</li></ul><h3 id="身份验证和授权-1" tabindex="-1"><a class="header-anchor" href="#身份验证和授权-1" aria-hidden="true">#</a> 身份验证和授权</h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 使用了安全的身份验证方案（如 JWT、OAuth）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 密码经过加密存储（使用 bcrypt 等）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 敏感操作需要重新验证</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 实现了权限控制，不同用户有不同权限</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Session 有过期时间</li></ul><h3 id="https-和传输安全" tabindex="-1"><a class="header-anchor" href="#https-和传输安全" aria-hidden="true">#</a> HTTPS 和传输安全</h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 生产环境使用 HTTPS</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> Cookie 设置了 Secure 和 HttpOnly 标志</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 使用了 SameSite Cookie 防止 CSRF</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 敏感数据传输时加密</li></ul><h3 id="依赖和第三方服务" tabindex="-1"><a class="header-anchor" href="#依赖和第三方服务" aria-hidden="true">#</a> 依赖和第三方服务</h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 定期运行 npm audit 检查漏洞</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 只使用可信的第三方包</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 定期更新依赖包</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 审查第三方包的权限</li></ul><h3 id="错误处理和日志" tabindex="-1"><a class="header-anchor" href="#错误处理和日志" aria-hidden="true">#</a> 错误处理和日志</h3><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 错误信息不暴露敏感信息</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 生产环境不显示详细的错误堆栈</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 日志不记录密码等敏感信息</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 实现了错误监控和告警</li></ul><h2 id="五、让-ai-帮你做安全检查" tabindex="-1"><a class="header-anchor" href="#五、让-ai-帮你做安全检查" aria-hidden="true">#</a> 五、让 AI 帮你做安全检查</h2><p>毫无疑问，AI 也能帮你发现并修复安全问题。</p><p>你可以让 AI 帮你审查代码的安全性：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>请从安全角度审查这段代码，找出潜在的安全问题：
【贴上你的代码】
重点检查：
<span class="token list punctuation">1.</span> 有没有 SQL 注入风险？
<span class="token list punctuation">2.</span> 有没有 XSS 攻击风险？
<span class="token list punctuation">3.</span> 用户输入是否经过验证？
<span class="token list punctuation">4.</span> 敏感信息是否暴露？
<span class="token list punctuation">5.</span> 错误处理是否安全？
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>AI 会给你详细的安全分析。</p><p>发现问题后，让 AI 帮你修复：</p><div class="language-markdown line-numbers-mode" data-ext="md"><pre class="language-markdown"><code>你提到了这段代码有 SQL 注入风险。请给我一个安全的实现方案，使用参数化查询。
这里的用户输入没有验证。请添加验证逻辑，确保邮箱格式正确，密码长度至少 8 位。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>但要注意，<strong>不要完全依赖 AI 的安全建议</strong>。AI 可能会遗漏一些问题，或者给出不够安全的方案。你要结合自己的判断，必要时查阅官方文档或者找多个 AI 大模型确认。</p><h3 id="使用安全扫描工具" tabindex="-1"><a class="header-anchor" href="#使用安全扫描工具" aria-hidden="true">#</a> 使用安全扫描工具</h3><p>除了 AI，还可以使用专门的安全扫描工具：</p><ul><li>Snyk：扫描依赖包的漏洞</li><li>SonarQube：代码质量和安全分析</li><li>OWASP ZAP：Web 应用安全测试</li></ul><p><img src="https://pic.yupi.icu/1/evo-by-snyk-hp-image_j0acql.png" alt=""></p><p>这些工具能自动发现很多安全问题。</p><h2 id="六、安全开发的习惯" tabindex="-1"><a class="header-anchor" href="#六、安全开发的习惯" aria-hidden="true">#</a> 六、安全开发的习惯</h2><p>安全不是一次性的工作，而是要养成习惯，时刻铭记着。</p><h3 id="最小权限原则" tabindex="-1"><a class="header-anchor" href="#最小权限原则" aria-hidden="true">#</a> 最小权限原则</h3><p>给每个用户、每个服务只分配必要的权限，不要给多余的权限。</p><p>比如，如果一个 API Key 只需要读取数据，就不要给它写入权限。如果一个用户只是普通用户，就不要给他管理员权限。</p><p>这样，即使某个密钥或账户被盗，损失也会小一些。</p><h3 id="定期轮换密钥" tabindex="-1"><a class="header-anchor" href="#定期轮换密钥" aria-hidden="true">#</a> 定期轮换密钥</h3><p>不要一个 API Key 用到天荒地老。定期更换密钥，比如每 3 个月或每 6 个月换一次。</p><p>大多数服务都支持创建多个 API Key。你可以先创建新的 Key，更新到项目中，确认没问题后，再删除旧的 Key。</p><h3 id="监控异常活动" tabindex="-1"><a class="header-anchor" href="#监控异常活动" aria-hidden="true">#</a> 监控异常活动</h3><p>很多 API 服务都提供了使用量监控和告警功能，记得开启，及时发现异常。</p><p>如果你的 API 调用量突然暴增，可能是 Key 被盗用了。如果有人尝试多次登录失败，可能是在暴力破解密码。</p><h3 id="保持更新" tabindex="-1"><a class="header-anchor" href="#保持更新" aria-hidden="true">#</a> 保持更新</h3><p>安全漏洞会不断被发现，软件包也会不断更新修复漏洞。定期更新你的依赖包，关注安全公告，及时修复已知的安全问题。</p><h3 id="备份数据" tabindex="-1"><a class="header-anchor" href="#备份数据" aria-hidden="true">#</a> 备份数据</h3><p>即使做了所有防护，还是可能出问题。建议定期备份数据，能让你在最坏的情况下也能恢复。</p><p>如果你使用了 Supabase 等第三方后端服务，可能会自动备份。如果是自己的数据库，要设置定期备份。</p><h2 id="写在最后" tabindex="-1"><a class="header-anchor" href="#写在最后" aria-hidden="true">#</a> 写在最后</h2><p>安全问题往往是最容易被忽视的，因为它不像功能或性能那样直观。但一旦出了安全问题，后果可能是灾难性的。</p><p>最后总结一下本文的要点：</p><ol><li>API Key 泄露是最大的风险：绝对不要把 API Key 写在代码里，要使用环境变量。</li><li>前端和后端要区分：敏感的操作必须在后端进行，不要相信前端的任何验证。</li><li>了解常见漏洞：SQL 注入、XSS、CSRF 等都是要防范的。</li><li>使用安全检查清单：每次发布前过一遍清单，确保没有遗漏。</li><li>养成安全习惯：最小权限、定期轮换密钥、监控异常、保持更新、备份数据。</li><li>善用工具：AI 和安全扫描工具能帮你发现问题，但不要完全依赖它们。</li></ol><p>安全是一个持续的过程，不是一劳永逸的。保持警惕，定期检查，才能保护好你的项目和用户。</p><p>希望这些安全防护技巧能帮你避免常见的安全问题，让你的 Vibe Coding 项目更加安全可靠。</p><p>学习辛苦了，给自己加个鸡腿 🍗，吃完就出发！</p><h2 id="推荐资源" tabindex="-1"><a class="header-anchor" href="#推荐资源" aria-hidden="true">#</a> 推荐资源</h2>`,133),u={href:"https://ai.codefather.cn",target:"_blank",rel:"noopener noreferrer"},d={href:"https://www.codefather.cn",target:"_blank",rel:"noopener noreferrer"},k={href:"https://www.mianshiya.com",target:"_blank",rel:"noopener noreferrer"},h={href:"https://www.laoyujianli.com",target:"_blank",rel:"noopener noreferrer"},m={href:"https://ai.mianshiya.com",target:"_blank",rel:"noopener noreferrer"};function v(b,g){const a=o("ExternalLinkIcon");return p(),i("div",null,[r,s("p",null,[n("1）鱼皮 AI 导航网站："),s("a",u,[n("AI 资源大全、最新 AI 资讯、免费 AI 教程"),e(a)])]),s("p",null,[n("2）编程导航学习圈："),s("a",d,[n("学习路线、编程教程、实战项目、求职宝典、交流答疑"),e(a)])]),s("p",null,[n("3）程序员面试八股文："),s("a",k,[n("实习/校招/社招高频考点、企业真题解析"),e(a)])]),s("p",null,[n("4）程序员写简历神器："),s("a",h,[n("专业模板、丰富例句、直通面试"),e(a)])]),s("p",null,[n("5）1 对 1 模拟面试："),s("a",m,[n("实习/校招/社招面试拿 Offer 必备"),e(a)])])])}const x=t(l,[["render",v],["__file","09VibeCodinganquanfanghujiqiao.html.vue"]]);export{x as default};
